def submit(path: Path) -> None:
            try:
                propose_template(self.output, path)
            except BaseException as exc:  # pragma: no cover - surfaced below
                errors.append(exc)

def run(*arguments: str) -> subprocess.CompletedProcess[str]:
            return subprocess.run(
                [sys.executable, str(ckb), "template", *arguments],
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=False,
            )

def _deep_context(**sections: dict[str, object]) -> dict[str, object]:
    sections["deep-reading"] = _section_context(
        links=[{"target": DEEP_TARGET, "purpose": "继续定位相关源码与记录", "kind": "internal"}]
    )
    return _context(**sections)
